def prog(): return os.path.basename(sys.argv[0])

def help_text():
    return f"""i3-style 1.0
Make your i3 config a bit more stylish

USAGE:
    {prog()} [FLAGS] [OPTIONS] [theme]

FLAGS:
    -h, --help        Prints help information
    -l, --list-all    Print a list of all available themes
    -r, --reload      Apply the theme by reloading the config
    -s, --save        Set the output file to the path of the input file
    -V, --version     Prints version information

OPTIONS:
    -c, --config <file>      The config file the theme should be applied to. Defaults to the default i3 location.
    -o, --output <file>      Apply the theme, attempt to validate the result, and write it to <file>
    -t, --to-theme <file>    Prints an i3-style theme based on the given config suitable for sharing with others
                             [default: ]

ARGS:
    <theme>    The theme to use
"""

def print_list():
    print('\nAvailable themes:\n')
    for n,d in THEME_DESCS:
        print(f"  {n:<18} - {d}")

def usage_select():
    print(f"USAGE:\n    {prog()} [FLAGS] [OPTIONS] [theme]\n\nSelect a theme as the first argument. Use `--list-all` to see the themes.")

def clap_error(msg):
    sys.stderr.write(msg + "\n\nUSAGE:\n    " + prog() + " [FLAGS] [OPTIONS] [theme]\n\nFor more information try --help\n")
    sys.exit(1)

def parse_args(argv):
    opts={'help':False,'version':False,'list':False,'reload':False,'save':False,'config':None,'output':None,'to_theme_present':False,'to_theme':'','theme':None}
    extras=[]; i=0
    def need_val(name, display):
        nonlocal i
        if i+1>=len(argv):
            sys.stderr.write(f"error: The argument '{display}' requires a value but none was supplied\n\nUSAGE:\n    {prog()} {display} --to-theme <file>\n\nFor more information try --help\n")
            sys.exit(1)
        i+=1; return argv[i]
    while i < len(argv):
        a=argv[i]
        if a=='--help': opts['help']=True
        elif a=='--version': opts['version']=True
        elif a=='--list-all': opts['list']=True
        elif a=='--reload': opts['reload']=True
        elif a=='--save': opts['save']=True
        elif a.startswith('--config='): opts['config']=a.split('=',1)[1]
        elif a=='--config': opts['config']=need_val('config','--config <file>')
        elif a.startswith('--output='): opts['output']=a.split('=',1)[1]
        elif a=='--output': opts['output']=need_val('output','--output <file>')
        elif a.startswith('--to-theme='):
            opts['to_theme_present']=True; opts['to_theme']=a.split('=',1)[1]
        elif a=='--to-theme':
            opts['to_theme_present']=True
            if i+1 < len(argv) and not argv[i+1].startswith('-'):
                i+=1; opts['to_theme']=argv[i]
        elif a.startswith('--'):
            clap_error(f"error: Found argument '{a}' which wasn't expected, or isn't valid in this context")
        elif a.startswith('-') and a!='-':
            # rudimentary short flag clusters; c/o require following value or attached tail
            j=1
            while j < len(a):
                ch=a[j]
                if ch=='h': opts['help']=True; j+=1
                elif ch=='V': opts['version']=True; j+=1
                elif ch=='l': opts['list']=True; j+=1
                elif ch=='r': opts['reload']=True; j+=1
                elif ch=='s': opts['save']=True; j+=1
                elif ch in ('c','o'):
                    tail=a[j+1:]
                    if tail:
                        val=tail; j=len(a)
                    else:
                        disp='--config <file>' if ch=='c' else '--output <file>'
                        val=need_val('x', disp); j=len(a)
                    opts['config' if ch=='c' else 'output']=val
                elif ch=='t':
                    opts['to_theme_present']=True
                    tail=a[j+1:]
                    if tail:
                        opts['to_theme']=tail; j=len(a)
                    elif i+1 < len(argv) and not argv[i+1].startswith('-'):
                        i+=1; opts['to_theme']=argv[i]; j=len(a)
                    else:
                        j+=1
                else:
                    clap_error(f"error: Found argument '-{ch}' which wasn't expected, or isn't valid in this context")
        else:
            if opts['theme'] is None: opts['theme']=a
            else: extras.append(a)
        i+=1
    if extras and not (opts['help'] or opts['version'] or opts['list']):
        clap_error(f"error: Found argument '{extras[0]}' which wasn't expected, or isn't valid in this context")
    return opts

def find_config():
    home=os.environ.get('HOME','')
    for p in [os.path.join(home,'.i3','config'), os.path.join(home,'.config','i3','config')]:
        if os.path.exists(p): return p
    return None

def validate_config(path):
    try:
        p=subprocess.run(['i3','-C','-c',path], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except FileNotFoundError as e:
        sys.stderr.write(f"Could not validate config with `i3 -C -c {path}` (is i3 in the PATH?) No such file or directory (os error 2)\n")
        sys.exit(1)
    if p.returncode != 0:
        sys.stderr.write(f"Could not validate config.\nUse `i3 -C -c {path}` to see validation errors.\n")
        sys.exit(1)

def normalize_hex(v):
    v=v.strip().strip('"').strip("'")
    return v

def parse_theme_file(path):
    try:
        lines=open(path).read().splitlines()
    except FileNotFoundError:
        sys.stderr.write(f"Could not open theme: {path} - No such file or directory (os error 2)\n Use `i3-style --list-all` to see the available themes.\n")
        sys.exit(1)
    colors={}; bar={}; win={}
    section=None; subsection=None
    for raw in lines:
        if not raw.strip() or raw.strip().startswith('#') or raw.strip()=='---': continue
        indent=len(raw)-len(raw.lstrip(' ')); s=raw.strip()
        if indent==0 and s.endswith(':'):
            section=s[:-1]; subsection=None; continue
        if section=='colors' and indent>=2 and ':' in s:
            k,v=s.split(':',1); colors[k.strip()]=normalize_hex(v)
        elif section in ('window_colors','bar_colors'):
            if indent==2 and s.endswith(':'):
                subsection=s[:-1]; continue
            if ':' in s:
                k,v=s.split(':',1); k=k.strip(); val=normalize_hex(v)
                if val in colors: val=colors[val]
                if not val.startswith('#') and val in colors: val=colors[val]
                if section=='window_colors':
                    if subsection:
                        win.setdefault(subsection,{})[k]=val
                    else:
                        # not expected for windows
                        pass
                else:
                    if subsection:
                        bar.setdefault(subsection,{})[k]=val
                    else:
                        bar[k]=val
    # flatten nested maps
    wflat={}
    for key in WIN_ORDER:
        d=win.get(key)
        if d and all(x in d for x in ['border','background','text','indicator']):
            wflat[key]=' '.join([d['border'],d['background'],d['text'],d['indicator']])
    bflat={}
    for k,v in bar.items():
        if isinstance(v,str): bflat[k]=v
    for key in ['focused_workspace','active_workspace','inactive_workspace','urgent_workspace']:
        d=bar.get(key)
        if isinstance(d,dict) and all(x in d for x in ['border','background','text']):
            bflat[key]=' '.join([d['border'],d['background'],d['text']])
    return {'bar':bflat,'win':wflat}

def load_theme(name):
    if name in THEMES:
        return THEMES[name]
    return parse_theme_file(name)

def line_no_nl(line):
    return line[:-1] if line.endswith('\n') else line

def color_indent(base):
    return base + ('\t' if '\t' in base and base.rstrip('\t')=='' else '  ')

def replace_bar_line(line, key, theme):
    indent=re.match(r'^(\s*)', line).group(1)
    if key not in theme['bar']:
        return line
    val=theme['bar'][key]
    if key in WORKSPACE_KEYS:
        toks=line.strip().split()
        extra=toks[3] if len(toks) >= 4 else ''  # key + three old colors; preserve the old text color as 4th value
        return f"{indent}{key} {val} {extra}".rstrip() if extra else f"{indent}{key} {val} "
    return f"{indent}{key} {val}"

def make_bar_color_lines(theme, base_indent='    '):
    out=[]
    for key in BAR_ORDER:
        if key not in theme['bar']: continue
        val=theme['bar'][key]
        if key in WORKSPACE_KEYS:
            out.append(f"{base_indent}{key} {val} ")
        else:
            out.append(f"{base_indent}{key} {val}")
    return out

