                    block, endi=process_colors_block(lines, i, theme)
                    out.extend(block); i=endi+1; continue
                # If this is a bar closing brace, insert a colors block if missing.
                if cur.strip().startswith('}'):
                    if not has_colors and theme['bar']:
                        out.append('  colors {')
                        out.extend(make_bar_color_lines(theme, '    '))
                        out.append('  }')
                        has_colors=True
                    out.append(cur); i+=1; break
                out.append(cur); i+=1
            continue
        out.append(line); i+=1
    for key in WIN_ORDER:
        if key in theme['win'] and key not in seen_win:
            out.append(f"client.{key} {theme['win'][key]}")
    return '\n'.join(out)+'\n'

def collect_config_colors(text):
    # Returns extracted structures plus ordered colors. Active workspace is intentionally ignored,
    # matching the observed generator.
    vals=[]; bar={}; win={}
    for raw in text.splitlines():
        s=raw.strip(); parts=s.split()
        if not parts: continue
        key=parts[0]
        if key in ('separator','background','statusline') and len(parts)>=2:
            bar[key]=[parts[1]]; vals.append(parts[1])
        elif key in ('focused_workspace','inactive_workspace','urgent_workspace') and len(parts)>=4:
            bar[key]=parts[1:4]; vals.extend(parts[1:4])
        elif key.startswith('client.') and len(parts)>=5:
            wk=key.split('.',1)[1]
            win[wk]=parts[1:5]; vals.extend(parts[1:5])
    return vals, bar, win

def color_aliases(vals):
    hex_to_alias={}; base_counts={}; ordered=[]
    for v in vals:
        if not v.startswith('#'): continue
        hx='#'+v[1:].upper()
        if hx in hex_to_alias: continue
        base=HEX_BASENAME.get(hx, 'color')
        c=base_counts.get(base,0)
        alias=base if c==0 else f"{base}-{c}"
        base_counts[base]=c+1
        hex_to_alias[hx]=alias; ordered.append((alias,hx))
    return hex_to_alias, ordered

def alias_for(hex_to_alias, v):
    return hex_to_alias.get('#'+v[1:].upper(), v)

def to_theme_yaml(text):
    vals, bar, win = collect_config_colors(text)
    aliases, ordered = color_aliases(vals)
    out=['---','meta:','  description: AUTOMATICALLY GENERATED THEME','colors:']
    for name,hx in ordered:
        out.append(f'  {name}: "{hx}"')
    out.append('window_colors:')
    mapping=[('focused','focused'),('focused_inactive','focused_inactive'),('unfocused','unfocused'),('urgent','urgent')]
    labels=['border','background','text','indicator']
    for key,_ in mapping:
        if key in win:
            out.append(f'  {key}:')
            for lab,val in zip(labels, win[key]):
                out.append(f'    {lab}: {alias_for(aliases,val)}')
    out.append('bar_colors:')
    for key in ['background','statusline','separator']:
        if key in bar:
            out.append(f'  {key}: {alias_for(aliases,bar[key][0])}')
    for key in ['focused_workspace','urgent_workspace']:
        if key in bar:
            out.append(f'  {key}:')
            for lab,val in zip(['border','background','text'], bar[key]):
                out.append(f'    {lab}: {alias_for(aliases,val)}')
    return '\n'.join(out)+'\n'

def main():
    opts=parse_args(sys.argv[1:])
    if opts['help']:
        sys.stdout.write(help_text()); return 0
    if opts['version']:
        print('i3-style 1.0'); return 0
    if opts['list']:
        print_list(); return 0
    if opts['to_theme_present']:
        cfg = opts['to_theme'] or opts['config'] or find_config()
        if not cfg:
            sys.stderr.write('Could not find i3 config\n'); return 1
        validate_config(cfg)
        # The original unwraps here; a normal Python traceback is acceptable for unusual cases.
        text=open(cfg).read()
        sys.stdout.write(to_theme_yaml(text)); return 0
    if not opts['theme']:
        usage_select(); return 1
    cfg=opts['config'] or find_config()
    if not cfg:
        sys.stderr.write('Could not find i3 config\n'); return 1
    validate_config(cfg)
    theme=load_theme(opts['theme'])
    try:
        text=open(cfg).read()
    except FileNotFoundError:
        # Usually validation catches this unless a fake i3 is used.
        raise
    result=transform_config(text, theme)
    outpath=opts['output'] or (cfg if opts['save'] else None)
    if outpath:
        n=random.randint(1_000_000_000,1_999_999_999)
        tmp=f'/tmp/i3-style/{n}/config-input'
        try:
            os.makedirs(os.path.dirname(tmp), exist_ok=True)
            open(tmp,'w').write(text)
        except Exception:
            pass
        sys.stderr.write(f'saving config at {cfg} to {tmp}\n')
        with open(outpath,'w') as f: f.write(result)
    else:
        sys.stdout.write(result)
    if opts['reload']:
        try:
            subprocess.run(['i3-msg','reload'], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except FileNotFoundError:
            pass
    return 0

if __name__=='__main__':
    sys.exit(main())
